 if(d.kind==='deleteRoute'){const r=routes.find(r=>r.id===d.id)!;return <Modal title="Удалить мост?" subtitle={r.name} busy={busy} onClose={close}><p className="modal-copy">Правила пересылки будут удалены с входного сервера. Сначала нужно отозвать активные конфиги этого маршрута.</p><ErrorText error={error}/><div className="modal-footer"><Button onClick={close} disabled={busy}>Отмена</Button><Button variant="destructive" disabled={busy} onClick={()=>void run(a=>a.deleteRoute(r.id),'Мост удалён').then(v=>{if(v)close()})}>Удалить мост</Button></div></Modal>}
